(() => {
  const HOST_ID = "iready-thing-host";
  const prev = document.getElementById(HOST_ID);
  if (prev) {
    if (prev.__stop) prev.__stop();
    prev.remove();
  }

  try {
    const bin = atob("");
    const buf = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    const ff = new FontFace("Nunito IR", buf, { weight: "200 1000" });
    ff.load().then((f) => document.fonts.add(f)).catch(() => {});
  } catch (e) {}

  const state = { quiet: false, auto: false, skip: false };
  let armed = false;
  let lock = 0;
  let minimized = false;

  const wins = () => {
    const out = [window];
    const walk = (w) => {
      for (let i = 0; i < w.frames.length; i++) {
        try {
          const f = w.frames[i];
          void f.document;
          out.push(f);
          walk(f);
        } catch (e) {}
      }
    };
    walk(window);
    return out;
  };

  const qa = (sel) =>
    wins().flatMap((w) => {
      try {
        return Array.from(w.document.querySelectorAll(sel));
      } catch (e) {
        return [];
      }
    });

  const vis = (el) => {
    if (!el || !el.ownerDocument || !el.ownerDocument.defaultView) return false;
    const cs = el.ownerDocument.defaultView.getComputedStyle(el);
    return (
      cs.display !== "none" &&
      cs.visibility !== "hidden" &&
      el.getClientRects().length > 0
    );
  };

  const visLoose = (el) =>
    vis(el) ||
    (el.labels && Array.from(el.labels).some(vis)) ||
    vis(el.parentElement);

  const isOff = (el) =>
    el.disabled ||
    el.readOnly ||
    el.getAttribute("aria-disabled") === "true" ||
    el.getAttribute("aria-readonly") === "true";

  const fast = (m) => {
    try {
      m.muted = true;
      m.__irm = true;
      m.defaultPlaybackRate = 16;
      m.playbackRate = 16;
    } catch (e) {}
  };

  const skipVideo = (m) => {
    const d = m.duration;
    fast(m);
    if (!isFinite(d) || d <= 0) return;
    const k = m.currentSrc || m.src;
    if (m.__sk !== k) {
      m.__sk = k;
      m.__t0 = Date.now();
      m.__fe = false;
    }
    try {
      if (m.currentTime < d - 0.1) m.currentTime = Math.max(0, d - 0.1);
    } catch (e) {}
    if (!m.__fe && (m.ended || Date.now() - m.__t0 > 1500)) {
      m.__fe = true;
      if (!m.ended) {
        try {
          m.pause();
        } catch (e) {}
        m.dispatchEvent(new Event("timeupdate"));
        m.dispatchEvent(new Event("ended"));
      }
    }
  };

  const patchWin = (w) => {
    if (w.__irt) return;
    w.__irt = true;

    const P = w.HTMLMediaElement.prototype;
    const op = P.play;
    P.play = function () {
      const isVid = this.tagName === "VIDEO";
      const r = op.apply(this, arguments);
      if (isVid && state.skip) {
        fast(this);
        setTimeout(() => skipVideo(this), 0);
      }
      if (!isVid && state.quiet) {
        fast(this);
        say("voice sped up and muted (audio element)");
      }
      return r;
    };

    ["play", "playing", "loadedmetadata", "canplay", "durationchange"].forEach((t) => {
      w.document.addEventListener(
        t,
        (e) => {
          const m = e.target;
          if (!m || !m.tagName) return;
          if (m.tagName === "AUDIO" && state.quiet) fast(m);
          if (m.tagName === "VIDEO" && state.skip) skipVideo(m);
        },
        true
      );
    });

    const s = w.speechSynthesis;
    if (s) {
      const os = s.speak.bind(s);
      s.speak = (u) => {
        if (state.quiet) {
          try {
            u.volume = 0;
            u.rate = 10;
          } catch (e) {}
        }
        return os(u);
      };
    }

    const ABS = w.AudioBufferSourceNode;
    if (ABS) {
      const st = ABS.prototype.start;
      ABS.prototype.start = function () {
        if (state.quiet) {
          try {
            this.playbackRate.value = 16;
          } catch (e) {}
          try {
            this.disconnect();
          } catch (e) {}
          say("voice sped up and muted (web audio)");
        }
        return st.apply(this, arguments);
      };
    }
  };

  const patchLibs = (w) => {
    const cj = w.createjs;

    const Hw = w.Howl;
    if (Hw && Hw.prototype && !Hw.prototype.__irt) {
      Hw.prototype.__irt = true;
      const op = Hw.prototype.play;
      Hw.prototype.play = function () {
        const id = op.apply(this, arguments);
        if (state.quiet) {
          try {
            this.mute(true, id);
            this.rate(16, id);
          } catch (e) {}
          say("voice sped up and muted (howler)");
        }
        return id;
      };
    }

    const t = cj && cj.Ticker;
    if (t && "framerate" in t) {
      if (state.skip) {
        if (t.framerate !== 240) {
          if (!t.__orig) t.__orig = t.framerate;
          t.framerate = 240;
        }
      } else if (t.__orig) {
        t.framerate = t.__orig;
        t.__orig = null;
      }
    }
  };

  const textboxSel =
    'textarea, input:not([type]), input[type="text"], input[type="number"], input[type="search"], input[type="email"], input[type="tel"], [contenteditable=""], [contenteditable="true"], [role="textbox"]';
  const choiceSel =
    'input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"], [role="option"], [role="menuitemradio"]';

  const needsAnswer = () => {
    const boxes = qa(textboxSel).filter((e) => vis(e) && !isOff(e));
    const emptyBox = boxes.some((e) => {
      const v = e.value !== undefined ? e.value : e.textContent;
      return String(v || "").trim() === "";
    });
    if (emptyBox) return true;
    const choices = qa(choiceSel).filter((e) => visLoose(e) && !isOff(e));
    if (choices.length) {
      const picked = choices.some(
        (e) =>
          e.checked === true ||
          e.getAttribute("aria-checked") === "true" ||
          e.getAttribute("aria-selected") === "true"
      );
      if (!picked) return true;
    }
    return false;
  };

  const pseudo = (b) => {
    const v = b.ownerDocument.defaultView;
    let out = "";
    ["::after", "::before"].forEach((p) => {
      try {
        out += v.getComputedStyle(b, p).content || "";
      } catch (e) {}
    });
    return out;
  };

  const isDone = (b) =>
    b.classList.contains("done") ||
    !!b.closest(".done") ||
    /done/i.test(pseudo(b)) ||
    /^done$/i.test((b.textContent || "").trim());

  const isGreen = (b) => {
    const c = b.ownerDocument.defaultView.getComputedStyle(b).backgroundColor;
    const m = c.match(/\d+(\.\d+)?/g);
    if (!m) return false;
    const [r, g, bl] = m.map(Number);
    return g > r + 30 && g > bl + 30;
  };

  const looksNext = (b) => {
    const t = (b.textContent || "").trim();
    const a = (b.getAttribute("aria-label") || "") + " " + (b.title || "");
    const c = b.getAttribute("class") || "";
    if (/^(continue|next)\b/i.test(t)) return true;
    if (/\b(continue|next)\b/i.test(a)) return true;
    if (/(continue|next)/i.test(c) && t.length < 20) return true;
    return !t && !!b.querySelector("svg, img") && isGreen(b);
  };

  const okBtn = (b) => {
    if (b.id === "nav-forward" || !vis(b) || isOff(b) || isDone(b)) return false;
    if (b.querySelector('button, [role="button"]')) return false;
    return true;
  };

  const findContinue = () =>
    qa(".tab-buttons button").find(
      (b) =>
        okBtn(b) &&
        !b.classList.contains("hidden") &&
        b.getAttribute("aria-hidden") !== "true" &&
        b.id !== "done-button" &&
        !/try|again|retry/i.test(pseudo(b))
    );

  const realClick = (el) => {
    const v = el.ownerDocument.defaultView;
    const r = el.getBoundingClientRect();
    const o = {
      bubbles: true,
      cancelable: true,
      view: v,
      clientX: r.left + r.width / 2,
      clientY: r.top + r.height / 2,
      button: 0,
    };
    const fire = (T, t) => {
      try {
        const C = T === "PointerEvent" && v.PointerEvent ? v.PointerEvent : v.MouseEvent;
        el.dispatchEvent(new C(t, o));
      } catch (e) {}
    };
    fire("PointerEvent", "pointerdown");
    fire("MouseEvent", "mousedown");
    fire("PointerEvent", "pointerup");
    fire("MouseEvent", "mouseup");
    fire("MouseEvent", "click");
  };

  const feedbackSel =
    '[class*="incorrect" i], [class*="wrong" i], [class*="tryagain" i], [class*="try-again" i]';

  const autoNext = () => {
    if (Date.now() < lock) return {};
    if (needsAnswer()) return { note: "waiting, something to answer" };
    if (qa(feedbackSel).some(vis)) return { note: "wrong answer, not clicking" };
    const b = findContinue();
    if (!b) return { note: "no continue button found" };
    lock = Date.now() + 1500;
    realClick(b);
    console.log("[iready-thing] clicked", b);
    return { note: "clicked " + describe(b), clicked: true };
  };

  const unlock = (el) => {
    el.removeAttribute("disabled");
    el.disabled = false;
    el.removeAttribute("aria-disabled");
    el.classList.remove("disabled", "is-disabled");
    el.style.pointerEvents = "auto";
  };

  const reactClick = (el) => {
    let n = el;
    for (let i = 0; i < 4 && n; i++, n = n.parentElement) {
      const k = Object.keys(n).find(
        (x) => x.startsWith("__reactProps$") || x.startsWith("__reactEventHandlers$")
      );
      const p = k && n[k];
      if (p && typeof p.onClick === "function") {
        p.onClick({
          type: "click",
          target: el,
          currentTarget: n,
          preventDefault() {},
          stopPropagation() {},
          persist() {},
          nativeEvent: new MouseEvent("click"),
          isTrusted: true,
        });
        return true;
      }
    }
    return false;
  };

  const forceNext = () => {
    const all = qa("#nav-forward");
    if (!all.length) return 0;
    armed = true;
    const shown = all.filter(vis);
    const el = (shown.length ? shown : all)[0];
    unlock(el);
    if (!reactClick(el)) realClick(el);
    return all.length;
  };

  const status = document.createElement("div");
  const IDLE = "-";
  let statusTimer = 0;
  let lastNote = "";
  const say = (msg, sticky) => {
    status.textContent = msg;
    clearTimeout(statusTimer);
    if (!sticky) {
      statusTimer = setTimeout(() => {
        status.textContent = IDLE;
        lastNote = "";
      }, 2800);
    }
  };

  const describe = (el) => {
    if (el.id) return "#" + el.id;
    const c = (el.getAttribute("class") || "").trim().split(/\s+/)[0];
    return el.tagName.toLowerCase() + (el.id ? "#" + el.id : "") + (c ? "." + c : "");
  };

  const sweep = () => {
    wins().forEach((w) => {
      patchWin(w);
      patchLibs(w);
    });
    if (state.quiet) {
      qa("audio").forEach(fast);
    } else {
      qa("audio").forEach((m) => {
        if (m.__irm) {
          m.__irm = false;
          m.muted = false;
          m.defaultPlaybackRate = 1;
          m.playbackRate = 1;
        }
      });
    }
    if (state.skip) {
      qa("video").forEach(skipVideo);
      qa('button, [role="button"]')
        .filter(
          (b) =>
            vis(b) &&
            /^skip( video| intro| animation)?$/i.test((b.textContent || "").trim())
        )
        .forEach((b) => b.click());
    }
    if (armed) qa("#nav-forward").forEach(unlock);
    if (state.auto) {
      const r = autoNext();
      if (r.note && r.note !== lastNote) {
        lastNote = r.note;
        say(r.note, !r.clicked);
      }
    }
  };

  const h = (tag, props, ...kids) => {
    const el = document.createElement(tag);
    if (props) {
      for (const k in props) {
        if (k.startsWith("on")) el.addEventListener(k.slice(2), props[k]);
        else el.setAttribute(k, props[k]);
      }
    }
    kids.flat().forEach((c) => el.append(c));
    return el;
  };

  const css = `
    :host { all: initial; display: block; }
    * { box-sizing: border-box; }
    .card {
      width: 100%;
      background: #fbfcff;
      color: #172033;
      border: 1px solid rgba(42, 58, 92, .14);
      border-radius: 16px;
      overflow: hidden;
      font-family: "Nunito IR", Nunito, "Nunito Sans", -apple-system, "Segoe UI", Roboto, sans-serif;
      display: flex;
      flex-direction: column;
      max-height: calc(100vh - 24px);
      box-shadow: 0 18px 50px rgba(19, 31, 57, .20), 0 2px 8px rgba(19, 31, 57, .10);
    }
    .head {
      padding: 14px 14px 14px 18px;
      background: #1a1a1a;
      color: #ffffff;
      cursor: grab;
      touch-action: none;
      user-select: none;
      -webkit-user-select: none;
      flex: none;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }
    .head.drag { cursor: grabbing; }
    .title-wrap { min-width: 0; }
    .title { font-size: 18px; font-weight: 900; letter-spacing: -.02em; }
    .subtitle { margin-top: 2px; font-size: 11px; font-weight: 700; color: rgba(255,255,255,.72); letter-spacing: .04em; text-transform: uppercase; }
    .head-actions { display: flex; gap: 6px; }
    .head-btn { width: 30px; height: 30px; padding: 0; border: 1px solid rgba(255,255,255,.25); border-radius: 8px; background: rgba(255,255,255,.12); color: #fff; font: inherit; font-size: 18px; line-height: 1; cursor: pointer; }
    .head-btn:hover, .head-btn:focus-visible { background: rgba(255,255,255,.24); outline: none; }
    .body {
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding: 14px;
      display: flex;
      flex-direction: column;
      gap: 9px;
      background: #f3f6fc;
    }
    .body[hidden], .status[hidden] { display: none; }
    .section-label { margin: 2px 4px 0; color: #617094; font-size: 11px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }
    .row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      padding: 13px 14px;
      background: #ffffff;
      border: 1px solid #dfe6f3;
      border-radius: 12px;
      box-shadow: 0 1px 2px rgba(26, 43, 78, .04);
      transition: border-color .15s, box-shadow .15s, transform .15s;
    }
    .row.tg { cursor: pointer; }
    .row.tg:hover, .row.tg:focus-visible { border-color: #bababa; box-shadow: 0 5px 14px rgba(45, 78, 145, .10); outline: none; }
    .row.tg:active { transform: scale(.99); }
    .txt { min-width: 0; }
    .name { font-size: 14px; font-weight: 900; line-height: 1.25; }
    .desc { margin-top: 3px; font-size: 12px; font-weight: 650; line-height: 1.4; color: #6d7890; }
    .sw {
      flex: none;
      width: 46px;
      height: 26px;
      border-radius: 999px;
      background: #cbd4e5;
      position: relative;
      transition: background .2s;
    }
    .sw::after {
      content: "";
      position: absolute;
      top: 3px;
      left: 3px;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: #ffffff;
      box-shadow: 0 1px 3px rgba(0,0,0,.2);
      transition: transform .2s;
    }
    .tg[aria-checked="true"] .sw { background: #000; }
    .tg[aria-checked="true"] .sw::after { transform: translateX(20px); }
    .go {
      flex: none;
      min-height: 40px;
      padding: 8px 15px;
      border: 0;
      border-radius: 9px;
      background: #000;
      color: #ffffff;
      font: inherit;
      font-size: 13px;
      font-weight: 900;
      cursor: pointer;
      box-shadow: 0 2px 5px rgba(50, 50, 50, 0.25);
    }
    .go:hover, .go:focus-visible { background: #1a1a1a; outline: none; }
    .go:active { transform: translateY(1px); }
    .calculator { padding: 13px 14px; background: #fff; border: 1px solid #dfe6f3; border-radius: 12px; }
    .calc-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
    .calc-title { font-size: 14px; font-weight: 900; }
    .calc-hint { color: #75809a; font-size: 11px; font-weight: 700; white-space: nowrap; }
    .calc-form { margin-top: 10px; }
    .calc-input { min-width: 0; width: 100%; height: 38px; padding: 0 10px; border: 1px solid #cbd6e8; border-radius: 8px; color: #172033; background: #f9fbff; font: 700 14px/1 "Nunito IR", Nunito, sans-serif; outline: none; }
    .calc-input:focus { border-color: #3159b4; box-shadow: 0 0 0 3px rgba(49,89,180,.13); }
    .calc-result { min-height: 18px; margin: 8px 2px 0; color: #000; font-size: 13px; font-weight: 900; }
    .calc-result.error { color: #b42318; }
    .status {
      flex: none;
      padding: 10px 16px;
      font-size: 12px;
      font-weight: 800;
      color: #55627e;
      border-top: 1px solid #dfe6f3;
      background: #ffffff;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
  `;

  status.setAttribute("role", "status");
  status.className = "status";
  status.textContent = IDLE;

  const host = document.createElement("div");
  host.id = HOST_ID;
  host.style.cssText =
    "position:fixed;top:12px;left:12px;z-index:2147483647;width:min(340px,calc(100vw - 24px));";
  const root = host.attachShadow({ mode: "open" });

  const toggleRow = (key, name, desc) => {
    const row = h(
      "div",
      { class: "row tg", role: "switch", tabindex: "0", "aria-checked": "false" },
      h("div", { class: "txt" }, h("div", { class: "name" }, name), h("div", { class: "desc" }, desc)),
      h("div", { class: "sw" })
    );
    const flip = () => {
      state[key] = !state[key];
      row.setAttribute("aria-checked", String(state[key]));
      if (key === "auto" && !state.auto) {
        status.textContent = IDLE;
        lastNote = "";
      }
      if (state[key]) sweep();
    };
    row.addEventListener("click", flip);
    row.addEventListener("keydown", (e) => {
      if (e.key === " " || e.key === "Enter") {
        e.preventDefault();
        flip();
      }
    });
    return row;
  };

  const buttonRow = (name, desc, label, fn) =>
    h(
      "div",
      { class: "row tg" },
      h("div", { class: "txt" }, h("div", { class: "name" }, name), h("div", { class: "desc" }, desc)),
      h("button", { class: "go", type: "button", onclick: fn }, label)
    );

  const calculator = () => {
    const input = h("input", { class: "calc-input", type: "text", inputmode: "decimal", autocomplete: "off", spellcheck: "false", placeholder: "e.g. (12 + 3) ^ 2 / 5", "aria-label": "Arithmetic expression" });
    const result = h("div", { class: "calc-result", "aria-live": "polite" }, "-");
    const calculate = () => {
      const source = input.value.trim();
      result.classList.remove("error");
      if (!source) { result.textContent = "-"; return; }
      const normalized = source.replace(/\s+/g, "").replace(/\^/g, "**");
      if (!/^[0-9+\-*/().]+$/.test(normalized) || /[+\-*/.]{3,}/.test(normalized)) {
        result.textContent = "I see non-math stuff";
        result.classList.add("error");
        return;
      }
      try {
        const value = Function('"use strict"; return (' + normalized + ");")();
        if (typeof value !== "number" || !Number.isFinite(value)) throw new Error("Idk tbh");
        result.textContent = "its " + Number(value.toPrecision(12)).toLocaleString(undefined, { maximumFractionDigits: 10 });
      } catch (e) {
        result.textContent = "Ts looks wrong";
        result.classList.add("error");
      }
    };
    input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); calculate(); } });
    input.addEventListener("input", () => { if (input.value.trim()) calculate(); else { result.textContent = "-"; result.classList.remove("error"); } });
    return h("div", { class: "calculator" }, h("div", { class: "calc-top" }, h("div", { class: "calc-title" }, "Quick calculator")), h("div", { class: "calc-form" }, input), result);
  };

  const head = h(
    "div",
    { class: "head" },
    h("div", { class: "title-wrap" }, h("div", { class: "title" }, "the iready thing")),
    h("div", { class: "head-actions" },
      h("button", { class: "head-btn", type: "button", "aria-label": "Minimize panel", title: "Minimize" }, "−"),
      h("button", { class: "head-btn", type: "button", "aria-label": "Close panel", title: "Close" }, "×")
    )
  );

  const body = h(
    "div",
    { class: "body" },
    h("div", { class: "section-label" }, "Controls"),
    toggleRow(
      "quiet",
      "Please shut up",
      "Shuts the guy up and shows question faster (put on music, its quiet)"
    ),
    toggleRow(
      "auto",
      "Next",
      "Spams the hell out of the Next button"
    ),
    buttonRow(
      "Nah, I'd win",
      "Goes to the next part even if you didn't get to it (spamming works)",
      "Go",
      () => {
        const n = forceNext();
        if (n) say("pressed #nav-forward (" + n + " found)");
        else say("no #nav-forward found");
      }
    ),
    toggleRow(
      "skip",
      "5 seconds not wasted",
      "skips the animation videos/example videos and just lets you do the work"
    ),
    h("div", { class: "section-label" }, "Calculate stuff"),
    calculator()
  );

  root.append(h("style", null, css), h("div", { class: "card" }, head, body, status));
  document.body.append(host);

  const [minimizeButton, closeButton] = head.querySelectorAll(".head-btn");
  [minimizeButton, closeButton].forEach((button) => button.addEventListener("pointerdown", (e) => e.stopPropagation()));
  minimizeButton.addEventListener("click", (e) => {
    e.stopPropagation();
    minimized = !minimized;
    body.hidden = minimized;
    status.hidden = minimized;
    minimizeButton.textContent = minimized ? "+" : "−";
    minimizeButton.setAttribute("aria-label", minimized ? "Expand panel" : "Minimize panel");
  });
  closeButton.addEventListener("click", (e) => {
    e.stopPropagation();
    host.__stop();
    host.remove();
  });

  let dragging = false;
  let dx = 0;
  let dy = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  head.addEventListener("pointerdown", (e) => {
    if (e.button > 0) return;
    dragging = true;
    const r = host.getBoundingClientRect();
    dx = e.clientX - r.left;
    dy = e.clientY - r.top;
    head.classList.add("drag");
    head.setPointerCapture(e.pointerId);
  });
  head.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    host.style.left = clamp(e.clientX - dx, 0, window.innerWidth - host.offsetWidth) + "px";
    host.style.top = clamp(e.clientY - dy, 0, window.innerHeight - 48) + "px";
  });
  const endDrag = () => {
    dragging = false;
    head.classList.remove("drag");
  };
  head.addEventListener("pointerup", endDrag);
  head.addEventListener("pointercancel", endDrag);

  const onResize = () => {
    const r = host.getBoundingClientRect();
    host.style.left = clamp(r.left, 0, Math.max(0, window.innerWidth - host.offsetWidth)) + "px";
    host.style.top = clamp(r.top, 0, Math.max(0, window.innerHeight - 48)) + "px";
  };
  window.addEventListener("resize", onResize);

  const timer = setInterval(sweep, 250);
  sweep();

  host.__stop = () => {
    clearInterval(timer);
    window.removeEventListener("resize", onResize);
    state.quiet = false;
    state.auto = false;
    state.skip = false;
    armed = false;
    sweep();
  };
})();
